class TemplateContext {
public:
    std::map<std::string, std::string> variables;
    std::map<std::string, std::function<std::string(const std::string&)>> filters;

    TemplateContext() {
        filters["upper"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::toupper);
            return r;
        };
        filters["lower"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::tolower);
            return r;
        };
        filters["trim"] = [](const std::string& s) {
            size_t start = s.find_first_not_of(" \t\n\r");
            size_t end = s.find_last_not_of(" \t\n\r");
            return (start == std::string::npos) ? "" : s.substr(start, end - start + 1);
        };
    }
};

class SafeExprEvaluator {
public:
    static bool is_safe_identifier(const std::string& id) {
        if (id.empty()) return false;
        if (!std::isalpha(id[0]) && id[0] != '_') return false;
        for (char c : id) {
            if (!std::isalnum(c) && c != '_' && c != '.') return false;
        }
        return true;
    }

    static bool contains_dangerous_pattern(const std::string& expr) {
        static const std::vector<std::string> blocked = {
            "system", "exec", "popen", "fork", "eval",
            "__", "import", "require", "include"
        };
        std::string lower_expr = expr;
        std::transform(lower_expr.begin(), lower_expr.end(), lower_expr.begin(), ::tolower);
        for (const auto& pattern : blocked) {
            if (lower_expr.find(pattern) != std::string::npos) return true;
        }
        return false;
    }
};

class TemplateDirectiveProcessor {
private:
    bool allow_include_;
    std::string base_path_;
    int recursion_depth_;
    static constexpr int MAX_RECURSION = 5;

public:
    TemplateDirectiveProcessor(const std::string& base_path, bool allow_include = false)
        : base_path_(base_path), allow_include_(allow_include), recursion_depth_(0) {}

    std::string resolve_include(const std::string& path) {
        if (!allow_include_) return "[include disabled]";
        if (path.find("..") != std::string::npos) return "[invalid path]";
        std::string full_path = base_path_ + "/" + path;
        std::ifstream file(full_path);
        if (!file.is_open()) return "[file not found]";
        std::stringstream ss;
        ss << file.rdbuf();
        return ss.str();
    }
};

class PDFTemplateEngine {
private:
    TemplateContext ctx_;
    std::unique_ptr<TemplateDirectiveProcessor> directive_proc_;
    static const std::vector<std::string> allowed_variables_;

    std::string apply_filter(const std::string& value, const std::string& filter_name) {
        auto it = ctx_.filters.find(filter_name);
        if (it != ctx_.filters.end()) {
            return it->second(value);
        }
        return value;
    }

    bool is_variable_accessible(const std::string& name) const {
        // Only allow explicitly whitelisted variables to be rendered
        if (name.find("secret") != std::string::npos) return false;
        if (name.find("token") != std::string::npos) return false;
        if (name.find("key") != std::string::npos) return false;
        if (name.find("password") != std::string::npos) return false;
        if (name.substr(0, 2) == "__") return false;
        return true;
    }

    std::string resolve_variable(const std::string& expr) {
        std::string var_name = expr;
        std::string filter_name;

        size_t pipe_pos = expr.find('|');
        if (pipe_pos != std::string::npos) {
            var_name = expr.substr(0, pipe_pos);
            filter_name = expr.substr(pipe_pos + 1);
            // trim whitespace
            var_name.erase(var_name.find_last_not_of(" ") + 1);
            filter_name.erase(0, filter_name.find_first_not_of(" "));
        }

        if (!is_variable_accessible(var_name)) {
            return "[access denied]";
        }

        auto it = ctx_.variables.find(var_name);
        std::string value = (it != ctx_.variables.end()) ? it->second : "";

        if (!filter_name.empty()) {
            value = apply_filter(value, filter_name);
        }
        return value;
    }

    std::string process_conditional(const std::string& condition, 
                                     const std::string& true_block,
                                     const std::string& false_block) {
        std::string resolved = resolve_variable(condition);
        if (!resolved.empty() && resolved != "0" && resolved != "false") {
            return render_template(true_block);
        }
        return render_template(false_block);
    }

    std::string process_loop_directive(const std::string& content,
                                       const std::string& iter_var,
                                       const std::string& collection_name) {
        if (!is_variable_accessible(collection_name)) return "";
        auto it = ctx_.variables.find(collection_name);
        if (it == ctx_.variables.end()) return "";

        std::string items_str = it->second;
        std::vector<std::string> items;
        std::stringstream ss(items_str);
        std::string item;
        while (std::getline(ss, item, ',')) {
            items.push_back(item);
        }

        std::string result;
        for (const auto& val : items) {
            ctx_.variables[iter_var] = val;
            result += render_template(content);
        }
        ctx_.variables.erase(iter_var);
        return result;
    }

public:
    PDFTemplateEngine(const std::string& base_path = "/app/templates")
        : directive_proc_(std::make_unique<TemplateDirectiveProcessor>(base_path, false)) {}

    void set_variable(const std::string& name, const std::string& value) {
        if (SafeExprEvaluator::is_safe_identifier(name)) {
            ctx_.variables[name] = value;
        }
    }

    void register_filter(const std::string& name, 
                         std::function<std::string(const std::string&)> fn) {
        // Only allow registration from code, not from templates
        ctx_.filters[name] = fn;
    }

    std::string render_template(const std::string& tmpl) {
        std::string result;
        size_t pos = 0;

        while (pos < tmpl.size()) {
            size_t var_start = tmpl.find("{{", pos);
            size_t dir_start = tmpl.find("{%", pos);

            if (var_start == std::string::npos && dir_start == std::string::npos) {
                result += tmpl.substr(pos);
                break;
            }

            if (var_start != std::string::npos && 
                (dir_start == std::string::npos || var_start < dir_start)) {
                result += tmpl.substr(pos, var_start - pos);
                size_t var_end = tmpl.find("}}", var_start + 2);
                if (var_end == std::string::npos) {
                    result += tmpl.substr(var_start);
                    break;
                }
                std::string expr = tmpl.substr(var_start + 2, var_end - var_start - 2);
                // Trim whitespace from expression
                expr.erase(0, expr.find_first_not_of(" "));
                expr.erase(expr.find_last_not_of(" ") + 1);

                if (!SafeExprEvaluator::is_safe_identifier(expr.substr(0, expr.find('|')))) {
                    result += "[invalid expression]";
                } else {
                    result += resolve_variable(expr);
                }
                pos = var_end + 2;
            } else {
                result += tmpl.substr(pos, dir_start - pos);
                size_t dir_end = tmpl.find("%}", dir_start + 2);
                if (dir_end == std::string::npos) {
                    result += tmpl.substr(dir_start);
                    break;
                }
                std::string directive = tmpl.substr(dir_start + 2, dir_end - dir_start - 2);
                directive.erase(0, directive.find_first_not_of(" "));
                directive.erase(directive.find_last_not_of(" ") + 1);

                if (directive.substr(0, 7) == "include") {
                    // Include is disabled in this deployment
                    result += "[include disabled]";
                }
                else if (directive.substr(0, 3) == "for") {
                    std::regex for_re(R"(for\s+(\w+)\s+in\s+(\w+))");
                    std::smatch m;
                    if (std::regex_match(directive, m, for_re)) {
                        std::string end_tag = "{% endfor %}";
                        size_t body_start = dir_end + 2;
                        size_t body_end = tmpl.find(end_tag, body_start);
                        if (body_end != std::string::npos) {
                            std::string body = tmpl.substr(body_start, body_end - body_start);
                            result += process_loop_directive(body, m[1], m[2]);
                            pos = body_end + end_tag.size();
                            continue;
                        }
                    }
                }
                else if (directive.substr(0, 6) == "filter") {
                    // Dynamic filter registration from templates is NOT allowed
                    result += "[filter directive disabled]";
                }
                pos = dir_end + 2;
            }
        }
        return result;
    }

    std::string generate_pdf_content(const std::string& template_str,
                                      const std::map<std::string, std::string>& data) {
        for (const auto& [key, value] : data) {
            set_variable(key, value);
        }

        std::string rendered = render_template(template_str);

        // Simulate PDF generation from rendered content
        std::string pdf_header = "%PDF-1.4\n";
        std::string pdf_body = rendered;
        return pdf_header + pdf_body;
    }
};

